#!/usr/bin/env python3
"""VIF + Partial Correlation analysis for K_eff and η_max."""

import os
os.environ["HF_HOME"] = "/root/autodl-tmp/.hf_cache"

import sys
sys.path.insert(0, "/root/cert_manip_resist_eval")

import json
import itertools
import numpy as np
import statsmodels.api as sm
from pathlib import Path
from scipy import stats

from src.unified_data_loader import (
    ALL_MODELS, DATASETS, ATTACKS,
    load_all_scores, load_pairs, load_mi_data,
)

EPS = 1e-6

MODEL_FAMILIES = {
    "qwen2.5-72b": "qwen", "qwen2.5-32b": "qwen", "qwen2.5-14b": "qwen",
    "llama3.1-70b": "meta", "llama3.1-8b": "meta",
    "mistral-large": "mistral",
    "claude-opus-4": "anthropic", "claude-sonnet-4": "anthropic",
    "claude-3-haiku": "anthropic",
    "gpt-5.5": "openai", "gpt-4.1": "openai",
    "gpt-4o": "openai", "gpt-4o-mini": "openai",
    "gemini-2.5-pro": "google", "gemini-2.5-flash": "google",
}


def _json_default(obj):
    if isinstance(obj, np.floating):
        v = float(obj)
        return None if (np.isnan(v) or np.isinf(v)) else v
    if isinstance(obj, np.integer):
        return int(obj)
    if isinstance(obj, np.ndarray):
        return obj.tolist()
    if isinstance(obj, np.bool_):
        return bool(obj)
    raise TypeError(f"Not JSON serializable: {type(obj)}")


def majority_vote(votes):
    counts = {"A": 0, "B": 0, "tie": 0}
    for v in votes:
        counts[v] = counts.get(v, 0) + 1
    mc = max(counts.values())
    winners = [k for k, c in counts.items() if c == mc]
    if len(winners) == 1:
        return winners[0]
    for w in winners:
        if w != "tie":
            return w
    return "tie"


def compute_individual_asr(clean_list, attacked_list, pairs):
    n = min(len(clean_list), len(attacked_list), len(pairs))
    n_flips = n_correct = 0
    for i in range(n):
        gt = pairs[i]["ground_truth_winner"]
        if clean_list[i].get("winner", "tie") == gt:
            n_correct += 1
            if attacked_list[i].get("winner", "tie") != gt:
                n_flips += 1
    return n_flips / max(n_correct, 1)


def compute_panel_asr(jids, clean, attacked, pairs):
    n = min(len(pairs), *(len(clean[j]) for j in jids),
            *(len(attacked[j]) for j in jids))
    n_flips = n_correct = 0
    for i in range(n):
        gt = pairs[i]["ground_truth_winner"]
        cv = majority_vote([clean[j][i].get("winner", "tie") for j in jids])
        if cv != gt:
            continue
        n_correct += 1
        av = majority_vote([attacked[j][i].get("winner", "tie") for j in jids])
        if av != gt:
            n_flips += 1
    return n_flips / max(n_correct, 1)


def partial_corr(x, y, z):
    """Partial correlation r(x, y | z) via residualization."""
    resid_x = sm.OLS(x, sm.add_constant(z)).fit().resid
    resid_y = sm.OLS(y, sm.add_constant(z)).fit().resid
    r, p = stats.pearsonr(resid_x, resid_y)
    return float(r), float(p)


def compute_vif_two_predictors(x1, x2):
    """VIF for two predictors = 1/(1-R^2) where R^2 from regressing x1 on x2."""
    fit = sm.OLS(x1, sm.add_constant(x2)).fit()
    return 1.0 / (1.0 - fit.rsquared)


def main():
    print("Loading data...")
    mi_data = load_mi_data()
    pairs = load_pairs()
    clean, attacked = load_all_scores()

    # Individual ASR
    ind_asr = {}
    for ds in DATASETS:
        for atk in ATTACKS:
            for mid in ALL_MODELS:
                if mid in clean[ds] and mid in attacked[ds][atk]:
                    ind_asr[(ds, atk, mid)] = compute_individual_asr(
                        clean[ds][mid], attacked[ds][atk][mid], pairs[ds]
                    )

    all_combos = list(itertools.combinations(range(len(ALL_MODELS)), 3))

    vif_per_condition = {}
    partial_per_condition = {}

    for ds in DATASETS:
        keff_data = mi_data["keff_per_panel"].get(ds, {})
        for atk in ATTACKS:
            cond = f"{ds}x{atk}"

            p_asrs, p_keffs, p_etas = [], [], []
            for combo in all_combos:
                jids = [ALL_MODELS[i] for i in combo]
                if not all((ds, atk, j) in ind_asr for j in jids):
                    continue
                pk = "|".join(jids)
                if pk not in keff_data:
                    continue

                keff = keff_data[pk]["keff"]
                etas = [ind_asr[(ds, atk, j)] for j in jids]
                eta_max = max(etas)

                cs = {j: clean[ds][j] for j in jids}
                ats = {j: attacked[ds][atk][j] for j in jids}
                p_asr = compute_panel_asr(jids, cs, ats, pairs[ds])

                p_asrs.append(p_asr)
                p_keffs.append(keff)
                p_etas.append(eta_max)

            n_panels = len(p_asrs)
            if n_panels < 10:
                continue

            p_asrs = np.array(p_asrs)
            p_keffs = np.array(p_keffs)
            p_etas = np.array(p_etas)

            if np.std(p_asrs) < 1e-10:
                continue

            log_keff = np.log(p_keffs)
            log_eta = np.log(p_etas + EPS)
            log_asr = np.log(p_asrs + EPS)

            # VIF between the two predictors
            vif = compute_vif_two_predictors(log_keff, log_eta)
            vif_per_condition[cond] = round(vif, 4)

            # Partial correlations
            r_eta_given_keff, p_eta_given_keff = partial_corr(log_eta, log_asr, log_keff)
            r_keff_given_eta, p_keff_given_eta = partial_corr(log_keff, log_asr, log_eta)

            partial_per_condition[cond] = {
                "eta_given_keff": {"r": round(r_eta_given_keff, 4), "p": float(f"{p_eta_given_keff:.6e}")},
                "keff_given_eta": {"r": round(r_keff_given_eta, 4), "p": float(f"{p_keff_given_eta:.6e}")},
            }

            print(f"{cond}: VIF={vif:.4f}  "
                  f"r(η|K)={r_eta_given_keff:+.4f} p={p_eta_given_keff:.2e}  "
                  f"r(K|η)={r_keff_given_eta:+.4f} p={p_keff_given_eta:.2e}")

    # Summary
    vif_vals = list(vif_per_condition.values())
    vif_summary = {
        "mean": round(float(np.mean(vif_vals)), 4),
        "min": round(float(np.min(vif_vals)), 4),
        "max": round(float(np.max(vif_vals)), 4),
    }

    eta_rs = [v["eta_given_keff"]["r"] for v in partial_per_condition.values()]
    keff_rs = [v["keff_given_eta"]["r"] for v in partial_per_condition.values()]
    eta_ps = [v["eta_given_keff"]["p"] for v in partial_per_condition.values()]
    keff_ps = [v["keff_given_eta"]["p"] for v in partial_per_condition.values()]

    eta_sig = sum(1 for p in eta_ps if p < 0.05)
    keff_sig = sum(1 for p in keff_ps if p < 0.05)

    partial_summary = {
        "eta_given_keff_mean_r": round(float(np.mean(eta_rs)), 4),
        "keff_given_eta_mean_r": round(float(np.mean(keff_rs)), 4),
        "eta_sig_count": f"{eta_sig}/{len(eta_rs)}",
        "keff_sig_count": f"{keff_sig}/{len(keff_rs)}",
    }

    output = {
        "vif": {
            "per_condition": vif_per_condition,
            **vif_summary,
        },
        "partial_correlation": {
            "per_condition": partial_per_condition,
            "summary": partial_summary,
        },
    }

    out_path = Path("/root/cert_manip_resist_eval/artifacts/results/plan001/vif_partial_corr.json")
    out_path.parent.mkdir(parents=True, exist_ok=True)
    with open(out_path, "w") as f:
        json.dump(output, f, indent=2, default=_json_default, ensure_ascii=False)

    print(f"\nVIF: mean={vif_summary['mean']}, min={vif_summary['min']}, max={vif_summary['max']}")
    print(f"Partial r(η|K): mean={partial_summary['eta_given_keff_mean_r']}, sig={partial_summary['eta_sig_count']}")
    print(f"Partial r(K|η): mean={partial_summary['keff_given_eta_mean_r']}, sig={partial_summary['keff_sig_count']}")
    print(f"\nSaved: {out_path}")


if __name__ == "__main__":
    main()
PYEOF
